package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Domain 1: පෘථිවි චලිත, අක්ෂාංශ-දේශාංශ හා වේලා කලාප
 * (Earth Rotation & Revolution, Seasons, Latitudes, Valid Longitudes 0°-180°, Real World Time Zones & Isolines)
 * Strictly unique, geographically valid, non-repetitive MCQs.
 */
internal object GeographyLiveExamEarthTimeBank {

  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun earthAndTimeQuestions(): List<QSpec> {
    val t = "පෘථිවි චලිත, අක්ෂාංශ-දේශාංශ හා වේලා කලාප"
    return listOf(
      q(t, "පෘථිවිය තම අක්ෂය වටා බටහිර සිට නැගෙනහිර දෙසට එක් සම්පූර්ණ වටයක් භ්‍රමණය වීමට ගතවන කාලය කොපමණද?",
        "පැය 23 විනාඩි 56 ක් (ආසන්නව පැය 24 කි)", "පැය 12 විනාඩි 30 ක් (ආසන්නව පැය 12 කි)", "දින 29 පැය 12 ක් (ආසන්නව චන්ද්‍ර මාසයකි)", "දින 365 පැය 6 ක් (ආසන්නව සූර්ය වර්ෂයකි)",
        "පෘථිවි භ්‍රමණය හේතුවෙන් දිවා රාත්‍රී ඇතිවන අතර සාමාන්‍ය සූර්ය දිනයක් පැය 24 ක් ලෙස සැලකේ."),
      q(t, "පෘථිවියේ අක්ෂය එහි කක්ෂ තලයේ ලම්බකයට අංශක කීයක ආනතියකින් ඇලව පවතීද?",
        "සිරස් ලම්බකයට අංශක 23.5° ක ආනතියකිනි", "සිරස් ලම්බකයට අංශක 45.0° ක ආනතියකිනි", "සිරස් ලම්බකයට අංශක 66.5° ක ආනතියකිනි", "සිරස් ලම්බකයට අංශක 90.0° ක ආනතියකිනි",
        "අක්ෂයේ 23.5° ආනතිය හා පරිභ්‍රමණය නිසා සෘතු භේදය සහ දිවා රාත්‍රී කාල වෙනස ඇතිවේ."),
      q(t, "පෘථිවි භ්‍රමණය නිසා සුළං හා සාගර ධාරා උතුරු අර්ධගෝලයේදී දකුණටත් දකුණු අර්ධගෝලයේදී වමටත් හැරවීමේ ආචරණය කුමක්ද?",
        "පෘථිවි භ්‍රමණය නිසා ඇතිවන කෝරියෝලිස් ආචරණය", "වායුගෝලයේ තාපය රඳවන හරිතාගාර ආචරණය", "චන්ද්‍රයාගේ ආකර්ෂණයෙන් හටගන්නා උදම් බල ආචරණය", "පෘථිවි කේන්ද්‍රය දෙසට ඇදෙන ගුරුත්වාකර්ෂණ ආචරණය",
        "පෘථිවිය බටහිර සිට නැගෙනහිරට කැරකීම නිසා චලනය වන වායු හා ජල ධාරා අපගමනය වේ."),
      q(t, "ශ්‍රී ලංකාවේ සම්මත වේලාව ග්‍රිනිච් මධ්‍යන්‍ය වේලාවට (UTC) වඩා කොපමණ වෙනසකින් පවතීද?",
        "ග්‍රිනිච් වේලාවට වඩා පැය 5 විනාඩි 30 ක් ඉදිරියෙනි", "ග්‍රිනිච් වේලාවට වඩා පැය 6 විනාඩි 00 ක් ඉදිරියෙනි", "ග්‍රිනිච් වේලාවට වඩා පැය 4 විනාඩි 30 ක් ඉදිරියෙනි", "ග්‍රිනිච් වේලාවට වඩා පැය 5 විනාඩි 30 ක් පසුපසිනි",
        "ශ්‍රී ලංකාව නැගෙනහිර දේශාංශ 82°30'E මත පදනම්ව UTC +5:30 සම්මත වේලාව භාවිත කරයි."),
      q(t, "ලන්ඩන් නුවර (0°) උදෑසන 8.00 වන විට ශ්‍රී ලංකාවේ (UTC +5:30) සම්මත වේලාව කීයද?",
        "එදිනම පස්වරු 1.30 (13:30)", "එදිනම පෙරවරු 2.30 (02:30)", "එදිනම පස්වරු 3.30 (15:30)", "එදිනම පෙරවරු 11.30 (11:30)",
        "ශ්‍රී ලංකාව GMT ට වඩා පැය 5 විනාඩි 30 ක් ඉදිරියෙන් සිටින බැවින් 8.00 + 5.30 = ප.ව. 1.30 වේ."),
      q(t, "පෘථිවිය සිය අක්ෂය වටා පැය 1 කදී භ්‍රමණය වන දේශාංශ ප්‍රමාණය අංශක කීයද?",
        "පැය 1 කදී දේශාංශ අංශක 15° ක් භ්‍රමණය වේ", "පැය 1 කදී දේශාංශ අංශක 1° ක් භ්‍රමණය වේ", "පැය 1 කදී දේශාංශ අංශක 30° ක් භ්‍රමණය වේ", "පැය 1 කදී දේශාංශ අංශක 4° ක් භ්‍රමණය වේ",
        "සම්පූර්ණ වටය 360° / පැය 24 = පැයකට 15° බැගින් භ්‍රමණය වේ."),
      q(t, "දේශාංශ 1° ක් හරහා පෘථිවිය භ්‍රමණය වීමට ගතවන කාලය මිනිත්තු කීයද?",
        "දේශාංශ අංශක 1° කට විනාඩි 4 ක කාලයකි", "දේශාංශ අංශක 1° කට විනාඩි 15 ක කාලයකි", "දේශාංශ අංශක 1° කට විනාඩි 60 ක කාලයකි", "දේශාංශ අංශක 1° කට විනාඩි 1 ක කාලයකි",
        "පැය 1 (විනාඩි 60) / 15° = අංශක 1 කට විනාඩි 4 කි."),
      q(t, "පෘථිවිය මත භූගෝලීය දේශාංශ පිහිටුම් නැගෙනහිරට හා බටහිරට මැනෙන උපරිම සීමාව කුමක්ද?",
        "ග්‍රිනිච් රේඛාවේ සිට 0° සිට 180° දක්වා", "ග්‍රිනිච් රේඛාවේ සිට 0° සිට 360° දක්වා", "ග්‍රිනිච් රේඛාවේ සිට 0° සිට 90° දක්වා", "ග්‍රිනිච් රේඛාවේ සිට 0° සිට 270° දක්වා",
        "ග්‍රිනිච් මධ්‍ය රේඛාව (0°) සිට නැගෙනහිරට 180°E දක්වාත් බටහිරට 180°W දක්වාත් දේශාංශ මනිනු ලැබේ."),
      q(t, "උතුරු හා දකුණු අක්ෂාංශ මැනීමේ උපරිම සීමාව සමකයේ සිට ධ්‍රැව දක්වා අංශක කීයද?",
        "සමකයේ සිට ධ්‍රැව දක්වා 0° සිට 90° දක්වා", "සමකයේ සිට ධ්‍රැව දක්වා 0° සිට 180° දක්වා", "සමකයේ සිට ධ්‍රැව දක්වා 0° සිට 45° දක්වා", "සමකයේ සිට ධ්‍රැව දක්වා 0° සිට 360° දක්වා",
        "සමකය 0° වන අතර උත්තර ධ්‍රැවය 90°N හා දක්ෂිණ ධ්‍රැවය 90°S වේ."),
      q(t, "ගුවන් යානයක් ජපානයේ සිට නැගෙනහිරට ගමන් කරමින් අන්තර්ජාතික දින රේඛාව (180°) පසු කළහොත් කැලැන්ඩර දිනයට සිදුවන්නේ කුමක්ද?",
        "දිනයක් අඩු වී එකම දිනය දෙවරක් ගත කිරීමට සිදුවේ", "දිනයක් වැඩි වී එක් කැලැන්ඩර දිනයක් මඟ හැරී යයි", "කැලැන්ඩර දිනය නොවෙනස්ව ඔරලෝසු පැය පමණක් වෙනස් වේ", "අන්තර්ජාතික සම්මුතිය අනුව දින හා වේලාව වෙනස් නොවේ",
        "බටහිර සිට නැගෙනහිරට (ආසියාවේ සිට ඇමරිකාවට) 180° රේඛාව පසු කිරීමේදී දිනයක් ආපසු යයි."),
      q(t, "ඇමරිකාවේ සිට බටහිර දෙසට (ජපානය දෙසට) 180° අන්තර්ජාතික දින රේඛාව පසු කරන නැවක දිනය වෙනස් වන්නේ කෙසේද?",
        "කැලැන්ඩර දිනයක් ඉදිරියට ගොස් එක් දිනක් මඟ හැරේ", "කැලැන්ඩර දිනයක් ආපසු ගොස් එකම දිනය දෙවරක් ලැබේ", "දිනය එසේම තිබී සම්පූර්ණ සතියේ දින පිළිවෙළ මාරු වේ", "පැසිෆික් කලාපයේදී නැවේ වේලාව පැය දෙකකින් ආපසු යයි",
        "නැගෙනහිර සිට බටහිරට දින රේඛාව තරණය කරන විට දිනයක් එකතු වේ (උදා: සඳුදා සිට අඟහරුවාදාට)."),
      q(t, "අන්තර්ජාතික දින රේඛාව (180° දේශාංශය) බේරිං සමුද්‍ර සන්ධිය හා පැසිෆික් දූපත් අසලදී වංගු සහිතව ඇඳ තිබෙන්නේ ඇයි?",
        "එකම රටකට හෝ දූපත් පෙළකට දින දෙකක් ඇතිවීම වැළැක්වීමට", "පැසිෆික් සාගරය හරහා යන නැව් ගමනාගමනය පාලනය කර ගැනීමට", "සමුද්‍ර දියවැල්වලින් දූපත්වලට ඇතිවන උණුසුම අඩු කර ගැනීමට", "උත්තර හා දක්ෂිණ චුම්බක ධ්‍රැව මඟහැර සිතියම් ඇඳ ගැනීමට",
        "සයිබීරියාව, ඇලූෂියන් දූපත් හා ෆීජි-කිරිබාටි දූපත් එකම දිනයේ තබා ගැනීමට රේඛාව නමා ඇත."),
      q(t, "ජූනි 21 වන දින සූර්යයා සෘජුවම මුදුන් වන ප්‍රධාන අක්ෂාංශ රේඛාව කුමක්ද?",
        "උතුරු අර්ධගෝලයේ කර්කටක නිවර්තනය (23.5° N)", "දකුණු අර්ධගෝලයේ මකර නිවර්තනය (23.5° S)", "පෘථිවියේ මධ්‍ය සමක රේඛාව (0° Equator)", "උතුරු ධ්‍රැවීය ආක්ටික් වෘත්තය (66.5° N)",
        "ජූනි 21 උත්තර අයනයේදී (Summer Solstice) උතුරු අර්ධගෝලයේ දිගම දිවා කාලය ඇතිවේ."),
      q(t, "දෙසැම්බර් 22 වන දින සූර්යයා සෘජුවම ලම්බකව බබළන ප්‍රධාන අක්ෂාංශ රේඛාව කුමක්ද?",
        "දකුණු අර්ධගෝලයේ මකර නිවර්තනය (23.5° S)", "උතුරු අර්ධගෝලයේ කර්කටක නිවර්තනය (23.5° N)", "පෘථිවියේ මධ්‍ය සමක රේඛාව (0° Equator)", "දකුණු ධ්‍රැවීය ඇන්ටාක්ටික් වෘත්තය (66.5° S)",
        "දෙසැම්බර් 22 දක්ෂිණ අයනයේදී (Winter Solstice) දකුණු අර්ධගෝලයට ගිම්හානය හා දිගම දිවා කාලය ලැබේ."),
      q(t, "මාර්තු 21 සහ සැප්තැම්බර් 23 යන දිනවලදී මුළු ලෝකයේම දිවා සහ රාත්‍රී කාලය පැය 12 බැගින් සමාන වන්නේ ඇයි?",
        "සූර්යයා සෘජුවම සමකය මත මුදුන් වී අර්ධගෝල දෙකම සමව ආලෝකවත් වීමෙන්", "එම දින දෙකේදී පෘථිවිය සිය අක්ෂය වටා භ්‍රමණය වීම මඳකට නවතින බැවින්", "චන්ද්‍රයා පෘථිවිය හා සූර්යයා අතරට පැමිණ ආලෝකය සමව බෙදා හරින බැවින්", "උත්තර හා දක්ෂිණ ධ්‍රැව දෙක එකම සෘජු තලයකට පැමිණ හිරුගෙන් ඉවත් වන බැවින්",
        "මෙම දින දෙක වසන්ත විෂුවය හා සරත් විෂුවය (Equinoxes) ලෙස හඳුන්වයි."),
      q(t, "66.5° N අක්ෂාංශයෙන් උතුරට ජූනි මාසයේදී පැය 24 පුරාම සූර්යයා නොබැස දිස්වීම හඳුන්වන සංසිද්ධිය කුමක්ද?",
        "ආක්ටික් කලාපයේ දක්නට ලැබෙන මධ්‍යම රාත්‍රී සූර්යයා", "පෘථිවියේ සෙවණැල්ල චන්ද්‍රයා මත වැටෙන චන්ද්‍ර ග්‍රහණය", "දිවා රාත්‍රී පැය 12 බැගින් සමාන වන විෂුව කාලය", "සූර්ය කිරණ ඇලව වැටෙන ශීත සෘතු අවම සූර්යතාපය",
        "උත්තර අයන කාලයේදී ආක්ටික් වෘත්තය තුළ අඛණ්ඩව දිවා ආලෝකය පවතී."),
      q(t, "ඊජිප්තුවේ කයිරෝ නගරයේ (30° E) දේශීය වේලාව පෙ.ව. 10.00 වන විට ලන්ඩන් (0°) වේලාව කීයද?",
        "එදිනම පෙරවරු 8.00 (08:00)", "එදිනම පස්වරු 12.00 (12:00)", "එදිනම පෙරවරු 6.00 (06:00)", "එදිනම පස්වරු 2.00 (14:00)",
        "30°E යනු GMT ට වඩා පැය 2 ක් ඉදිරියෙන් (30 / 15 = 2) බැවින් ලන්ඩන් වේලාව 10 - 2 = පෙ.ව. 8.00 වේ."),
      q(t, "ජපානයේ ටෝකියෝ නුවර 135° E දේශාංශයේ පිහිටයි. ග්‍රිනිච් (0°) වේලාව පෙ.ව. 6.00 වන විට ටෝකියෝ නුවර වේලාව කුමක්ද?",
        "එදිනම පස්වරු 3.00 (15:00)", "එදිනම පෙරවරු 9.00 (09:00)", "එදිනම පස්වරු 6.00 (18:00)", "එදිනම පස්වරු 12.00 (12:00)",
        "135° / 15° = පැය 9 ක් ඉදිරියෙන් බැවින් 6.00 + පැය 9 = ප.ව. 3.00 වේ."),
      q(t, "ඇමරිකාවේ නිව්යෝර්ක් නගරය (75° W) සහ ලන්ඩන් (0°) අතර පවතින භූගෝලීය කාල වෙනස කොපමණද?",
        "නිව්යෝර්ක් වේලාව ලන්ඩනයට වඩා පැය 5 ක් පසුපසිනි", "නිව්යෝර්ක් වේලාව ලන්ඩනයට වඩා පැය 5 ක් ඉදිරියෙනි", "නිව්යෝර්ක් වේලාව ලන්ඩනයට වඩා පැය 3 ක් පසුපසිනි", "නිව්යෝර්ක් වේලාව ලන්ඩනයට වඩා පැය 8 ක් ඉදිරියෙනි",
        "75°W / 15° = පැය 5 කි. බටහිරින් පිහිටි බැවින් කාලය පසුපසින් පවතී."),
      q(t, "සිඩ්නි නුවර (150° E) හා රියෝ ද ජැනයිරෝ (45° W) අතර පවතින මුළු දේශාංශ අන්තරය හා කාල වෙනස කොපමණද?",
        "දේශාංශ අංශක 195° හා පැය 13 ක කාල වෙනසකි", "දේශාංශ අංශක 105° හා පැය 7 ක කාල වෙනසකි", "දේශාංශ අංශක 45° හා පැය 3 ක කාල වෙනසකි", "දේශාංශ අංශක 150° හා පැය 10 ක කාල වෙනසකි",
        "ප්‍රතිවිරුද්ධ අර්ධගෝල දෙකක පිහිටි බැවින් දේශාංශ එකතු වේ: 150 + 45 = 195°; 195 / 15 = පැය 13 කි."),
      q(t, "ඉන්දියාවේ හා ශ්‍රී ලංකාවේ සම්මත වේලාව ගණනය කිරීම සඳහා මධ්‍යම රේඛාව ලෙස තෝරාගෙන ඇති දේශාංශය කුමක්ද?",
        "නැගෙනහිර දේශාංශ 82°30' E සම්මත මධ්‍ය රේඛාව", "නැගෙනහිර දේශාංශ 80°00' E සම්මත මධ්‍ය රේඛාව", "නැගෙනහිර දේශාංශ 90°00' E සම්මත මධ්‍ය රේඛාව", "නැගෙනහිර දේශාංශ 75°00' E සම්මත මධ්‍ය රේඛාව",
        "82.5° / 15° = පැය 5.5 (පැය 5 විනාඩි 30) බැවින් UTC +5:30 සම්මත වේලාව ලැබේ."),
      q(t, "ශ්‍රී ලංකාව පිහිටා ඇති නිරපේක්ෂ භූගෝලීය පිහිටීම (Absolute Location) කුමන අක්ෂාංශ හා දේශාංශ කලාපය තුළ වේද?",
        "උතුරු අක්ෂාංශ 5°55'-9°51' N හා නැගෙනහිර දේශාංශ 79°41'-81°53' E", "දකුණු අක්ෂාංශ 5°55'-9°51' S හා නැගෙනහිර දේශාංශ 79°41'-81°53' E", "උතුරු අක්ෂාංශ 5°55'-9°51' N හා බටහිර දේශාංශ 79°41'-81°53' W", "උතුරු අක්ෂාංශ 20°10'-25°30' N හා නැගෙනහිර දේශාංශ 79°41'-81°53' E",
        "ශ්‍රී ලංකාව සමකයට ආසන්නව උතුරු අර්ධගෝලයේ හා නැගෙනහිර අර්ධගෝලයේ පිහිටි දූපතකි."),
      q(t, "අක්ෂාංශ අංශක 1° ක පොළොව මත සැබෑ දුර ආසන්න වශයෙන් කිලෝමීටර් කීයක් වේද?",
        "ආසන්න වශයෙන් කිලෝමීටර් 111 ක දුරකි", "ආසන්න වශයෙන් කිලෝමීටර් 15 ක දුරකි", "ආසන්න වශයෙන් කිලෝමීටර් 500 ක දුරකි", "ආසන්න වශයෙන් කිලෝමීටර් 1,000 ක දුරකි",
        "පෘථිවි පරිධිය ආසන්නව 40,000 km / 360° = ~111 km බැවින් අක්ෂාංශ 1° ≈ 111 km වේ."),
      q(t, "පෘථිවිය මත දේශාංශ රේඛා දෙකක් අතර පවතින සත්‍ය දුර ප්‍රමාණය ධ්‍රැව දෙසට යන විට කෙසේ වෙනස් වේද?",
        "සමකයේදී උපරිම වී ධ්‍රැවයේදී ශුන්‍ය බවට පත්වේ", "සමකයේ සිට ධ්‍රැව දක්වාම කි.මී. 111 ලෙස සමාන වේ", "සමකයේදී අවම වී ධ්‍රැව දෙසට යත්ම වැඩි වේ", "සමකයේදී ශුන්‍ය වී නිවර්තන රේඛාවල උපරිම වේ",
        "සියලු දේශාංශ රේඛා උත්තර හා දක්ෂිණ ධ්‍රැවවලදී එක්වන බැවින් ඒවා සමාන්තර නොවේ."),
      q(t, "අක්ෂාංශ රේඛා අතරින් පෘථිවිය සමාන අර්ධගෝල දෙකකට බෙදන 'මහා වෘත්තයක්' වන එකම අක්ෂාංශ රේඛාව කුමක්ද?",
        "0° අක්ෂාංශය වන සමක රේඛාව (Equator)", "23.5° N හි පිහිටි කර්කටක නිවර්තන රේඛාව", "23.5° S හි පිහිටි මකර නිවර්තන රේඛාව", "66.5° N හි පිහිටි ආක්ටික් වෘත්ත රේඛාව",
        "පෘථිවිය හරි මැදින් සමාන අර්ධගෝල දෙකකට බෙදන එකම අක්ෂාංශ රේඛාව සමකයයි."),
      q(t, "සමකයට ආසන්නව පිහිටි බැවින් ශ්‍රී ලංකාවේ වසර පුරාම දක්නට ලැබෙන ප්‍රධාන කාලගුණික හා ආලෝක ලක්ෂණය කුමක්ද?",
        "දිවා රාත්‍රී කාල වෙනස අඩු වීම හා සෘතු 4 නොමැති වීම", "වසරකට මාස 6 ක් අඛණ්ඩ රාත්‍රී අඳුර පැවතීම", "නිරන්තර හිම පතනය සහ අධික ශීත සෘතු උෂ්ණත්වය", "සූර්යයා කිසිදා ඉහළින් නොපිහිටා ඇලවම පැවතීම",
        "උතුරු අක්ෂාංශ 6°-10° අතර පිහිටි නිසා ශ්‍රී ලංකාවට වසර පුරා ඉහළ සූර්යාලෝකයක් ලැබේ."),
      q(t, "පෘථිවිය සූර්යයා වටා ඉලිප්සාකාර කක්ෂයක ගමන් කිරීමේදී සූර්යයාට වඩාත්ම ආසන්නව පිහිටන අවස්ථාව හඳුන්වන්නේ කුමන නමින්ද?",
        "සූර්යයාට ආසන්නතම අවස්ථාව වන සූර්ය සමීපකය (Perihelion)", "සූර්යයාගෙන් දුරස්ථම අවස්ථාව වන සූර්ය දුරකය (Aphelion)", "දිවා රාත්‍රී සමාන වන වසන්ත විෂුව දිනය (Equinox)", "සූර්යයා නිවර්තනයකට මුදුන් වන අයන දිනය (Solstice)",
        "කි.මී. මිලියන 147 ක් පමණ දුරින් සූර්යයාට ආසන්නතම අවස්ථාව Perihelion වන අතර ජූලි මස Aphelion (මිලියන 152) වේ."),
      q(t, "කාලගුණ විද්‍යා සිතියම්වල සමාන වායුගෝලීය පීඩනයක් පවතින ස්ථාන යා කරමින් අඳින රේඛා කවරේද?",
        "සමාන වායු පීඩන දක්වන සමපීඩන රේඛා (Isobars)", "සමාන උෂ්ණත්වය දක්වන සමෝෂ්ණ රේඛා (Isotherms)", "සමාන වර්ෂාපතනය දක්වන සමවර්ෂා රේඛා (Isohyets)", "සමාන උන්නතාංශය දක්වන සමෝච්ච රේඛා (Contours)",
        "වායු පීඩනය මිලිබාර් හෝ හෙක්ටොපැස්කල් වලින් මැන Isobars මඟින් දක්වයි."),
      q(t, "යම් කලාපයක සමාන වාර්ෂික හෝ මාසික වර්ෂාපතනයක් ලැබෙන ස්ථාන යා කර අඳින රේඛාව කුමක්ද?",
        "සමාන වර්ෂාපතනය දක්වන සමවර්ෂා රේඛා (Isohyets)", "සමාන වායු පීඩනය දක්වන සමපීඩන රේඛා (Isobars)", "සමාන ලවණතාව දක්වන සමලවණ රේඛා (Isohalines)", "සමාන උෂ්ණත්වය දක්වන සමෝෂ්ණ රේඛා (Isotherms)",
        "Isohyets සිතියම් මඟින් තෙත් හා වියළි කලාප වෙන් කර හඳුනාගැනීම පහසු කරයි."),
      q(t, "කාලගුණ සිතියමක සමාන සූර්යාලෝක පැය ගණනක් ලැබෙන ස්ථාන යා කර අඳින රේඛා හඳුන්වන්නේ කුමන නමින්ද?",
        "සමාන සූර්යාලෝකය දක්වන සමසූර්ය රේඛා (Isohels)", "සමාන වර්ෂාපතනය දක්වන සමවර්ෂා රේඛා (Isohyets)", "සමාන වලාකුළු ප්‍රමාණය දක්වන සමමේඝ රේඛා (Isonephs)", "සමාන සාගර ගැඹුර දක්වන සම ගැඹුරු රේඛා (Isobaths)",
        "Isohels සූර්යාලෝකය ද, Isonephs වලාකුළු ආවරණය ද, Isotherms උෂ්ණත්වය ද නිරූපණය කරයි."),
      q(t, "විශාල භූමි ප්‍රමාණයක් නැගෙනහිර සිට බටහිරට විහිදෙන රුසියාව වැනි රටක ක්‍රියාත්මක වන වේලා කලාප ගණන කීයද?",
        "විවිධ සම්මත වේලා කලාප 11 ක් ක්‍රියාත්මක වේ", "මුළු රටටම සම්මත වේලා කලාප 1 ක් ක්‍රියාත්මක වේ", "ප්‍රධාන සම්මත වේලා කලාප 2 ක් ක්‍රියාත්මක වේ", "පරිපාලන සම්මත වේලා කලාප 24 ක් ක්‍රියාත්මක වේ",
        "රුසියාව දේශාංශ 160° කට වඩා පළලින් යුක්ත බැවින් සම්මත වේලා කලාප 11 ක් භාවිත කරයි."),
      q(t, "ලෝකය සම්මත වේලා කලාප (Time Zones) 24 කට බෙදා ඇත්තේ කුමන දේශාංශ පරතරය පදනම් කරගෙනද?",
        "සෑම දේශාංශ 15° කටම පැය 1 ක වේලා කලාපය බැගින්", "සෑම දේශාංශ 30° කටම පැය 1 ක වේලා කලාපය බැගින්", "සෑම දේශාංශ 10° කටම පැය 2 ක වේලා කලාපය බැගින්", "සෑම දේශාංශ 5° කටම පැය 1 ක වේලා කලාපය බැගින්",
        "360° / 24 = 15° බැගින් ග්‍රිනිච් (0°) මධ්‍ය කර 15° පටි 24 ක් ලෙස වේලා කලාප සැකසේ."),
      q(t, "රාජ්‍ය පරිපාලන පහසුව සඳහා භූගෝලීය වශයෙන් පුළුල් වුවද මුළු රටටම එක් තනි සම්මත වේලාවක් (UTC +8) භාවිත කරන ආසියානු රට කුමක්ද?",
        "නැගෙනහිර ආසියාවේ පිහිටි චීන මහජන සමූහාණ්ඩුව", "ආසියාව හා යුරෝපය පුරා විහිදුණු රුසියානු සමූහාණ්ඩුව", "උතුරු ඇමරිකාවේ විශාලතම රාජ්‍යය වන කැනඩාව", "ප්‍රාන්ත පනහකින් සමන්විත ඇමරිකා එක්සත් ජනපදය",
        "චීනය භූගෝලීයව කලාප 5 ක විහිදී තිබුණද ජාතික සම්මතය ලෙස බීජිං වේලාව (+08:00) පමණක් භාවිත කරයි."),
      q(t, "ග්‍රිනිච් මධ්‍ය රේඛාව (0° Prime Meridian) ගමන් කරන යුරෝපීය හා අප්‍රිකානු රටවල් කිහිපයක් නම් කරන්න.",
        "එක්සත් රාජධානිය, ප්‍රංශය, ස්පාඤ්ඤය, ඇල්ජීරියාව සහ ඝානාව", "ජපානය, චීනය, දකුණු කොරියාව, ඉන්දියාව සහ ශ්‍රී ලංකාව", "බ්‍රසීලය, ආර්ජන්ටිනාව, චිලී, පේරු සහ කොලොම්බියාව", "ඕස්ට්‍රේලියාව, නවසීලන්තය, පැපුවා නිව්ගිනියාව සහ ෆීජි",
        "0° දේශාංශ රේඛාව ලන්ඩනයේ ග්‍රිනිච් නිරීක්ෂණාගාරය හරහා දකුණට බටහිර යුරෝපය හා බටහිර අප්‍රිකාව ඔස්සේ ගමන් කරයි."),
      q(t, "සමකය (0° Equator) හරහා ගමන් නොකරන මහාද්වීප කාණ්ඩය නිවැරදිව තෝරන්න.",
        "යුරෝපය, උතුරු ඇමරිකාව සහ ඇන්ටාක්ටිකාව යන මහාද්වීප", "දකුණු ඇමරිකාව, අප්‍රිකාව සහ ආසියානු දූපත් සමූහය", "අප්‍රිකාව, දකුණු ඇමරිකාව සහ ඉන්දුනීසියානු ආසියාව", "මධ්‍යම අප්‍රිකාව සහ උතුරු දකුණු ඇමරිකා ප්‍රදේශ",
        "සමකය දකුණු ඇමරිකාව, අප්‍රිකාව සහ ආසියාවේ (ඉන්දුනීසියානු දූපත්) හරහා ගමන් කරයි."),
      q(t, "කර්කටක නිවර්තනය, සමකය සහ මකර නිවර්තනය යන ප්‍රධාන අක්ෂාංශ රේඛා තුනම හරහා ගමන් කරන එකම මහාද්වීපය කුමක්ද?",
        "උතුරු හා දකුණු අර්ධගෝල දෙකේම පිහිටි අප්‍රිකා මහාද්වීපය", "ලෝකයේ විශාලතම භූමි ස්කන්ධය වන ආසියා මහාද්වීපය", "සෞම්‍ය කලාපයේ පිහිටි යුරෝපා මහාද්වීපය", "බටහිර අර්ධගෝලයේ පිහිටි දකුණු ඇමරිකා මහාද්වීපය",
        "උතුරු-දකුණු දිගු පිහිටීම නිසා ප්‍රධාන නිවර්තන රේඛා තුනම අප්‍රිකානු මහාද්වීපය හරහා විහිදේ."),
      q(t, "ලෝක දේශගුණික කලාප අතරින් 'නිවර්තන කලාපය' (Tropics / Torrid Zone) ලෙස හැඳින්වෙන්නේ කුමන අක්ෂාංශ සීමා අතර කලාපයද?",
        "23.5° N කර්කටක නිවර්තනය හා 23.5° S මකර නිවර්තනය අතර", "66.5° N ආක්ටික් වෘත්තය හා 90° N උත්තර ධ්‍රැවය අතර", "30° N උපනිවර්තන කලාපය හා 60° N උපධ්‍රැවීය කලාපය අතර", "45° S මධ්‍ය අක්ෂාංශය හා 90° S දක්ෂිණ ධ්‍රැවය අතර",
        "සූර්යයා සෘජුවම මුදුන් වන සීමාව නිවර්තන කලාපය (Torrid Zone) ලෙස හැඳින්වේ."),
      q(t, "23.5° සිට 66.5° දක්වා උතුරු හා දකුණු අර්ධගෝලවල පිහිටි, පැහැදිලි සෘතු 4 ක් දක්නට ලැබෙන තාප කලාපය කුමක්ද?",
        "සෘතු 4 ක් පැහැදිලිව ඇති සෞම්‍ය කලාපය (Temperate Zone)", "වසර පුරා උණුසුම් නිවර්තන කලාපය (Torrid Zone)", "වසර පුරා අධික සීතල ශීත කලාපය (Frigid Zone)", "0° ආසන්නයේ පිහිටි සමක තෙත් කලාපය (Equatorial Zone)",
        "මධ්‍ය අක්ෂාංශ ප්‍රදේශවල ගිම්හාන, සරත්, ශීත හා වසන්ත යන සෘතු 4 පැහැදිලිව ඇතිවේ."),
      q(t, "පෘථිවිය මත 66.5° සිට 90° දක්වා අක්ෂාංශ අතර පිහිටි, වසරේ වැඩි කාලයක් අයිස්වලින් වැසී ඇති කලාපය කුමක්ද?",
        "ධ්‍රැව ආශ්‍රිතව පිහිටි ධ්‍රැවීය හෙවත් ශීත කලාපය (Frigid Zone)", "නිවර්තන දෙක අතර පිහිටි උණුසුම් නිවර්තන කලාපය", "මධ්‍ය අක්ෂාංශවල පිහිටි ශීත හා ග්‍රීෂ්ම මධ්‍යධරණී කලාපය", "සමක රේඛාව දෙපස පිහිටි අධික වර්ෂා සමක කලාපය",
        "සූර්ය කිරණ ඉතා ඇලව පතිත වන බැවින් මෙම කලාපවල උෂ්ණත්වය අතිශයින් අඩුය."),
      q(t, "පෘථිවිය සූර්යයා වටා පරිභ්‍රමණය වීමේදී (Revolution) එක් වටයක් සම්පූර්ණ කිරීමට ගතවන කාලය නිවැරදිව සඳහන් කරන්න.",
        "ආසන්න වශයෙන් දින 365 පැය 6 ක කාලයකි", "ආසන්න වශයෙන් දින 360 පැය 0 ක කාලයකි", "ආසන්න වශයෙන් දින 29 පැය 12 ක කාලයකි", "ආසන්න වශයෙන් පැය 23 විනාඩි 56 ක කාලයකි",
        "අතිරේක පැය 6 බැගින් වසර 4 කට වරක් එක්වී පෙබරවාරි මාසයට දින 29 ක් (අධික අවුරුද්ද) එක් කෙරේ."),
      q(t, "ඩකා නගරයේ (90° E) දේශීය වේලාව ප.ව. 4.00 වන විට ග්‍රිනිච් මධ්‍ය රේඛාවේ (0°) වේලාව කීයද?",
        "එදිනම පෙරවරු 10.00 (10:00)", "එදිනම රාත්‍රී 10.00 (22:00)", "එදිනම පෙරවරු 4.00 (04:00)", "එදිනම මධ්‍යහ්න 12.00 (12:00)",
        "90°E / 15° = පැය 6 ක් ඩකා නුවර ඉදිරියෙන් සිටී. එබැවින් ලන්ඩන් වේලාව = 16:00 - 6 = පෙ.ව. 10.00 වේ."),
      q(t, "පෘථිවි අක්ෂය ඇල නොවී කක්ෂ තලයට සම්පූර්ණයෙන්ම ලම්බකව පැවතියේ නම් පෘථිවිය මත සිදුවන ප්‍රධාන වෙනස කුමක්ද?",
        "සෘතු භේදය නොමැති වී දිවා රාත්‍රී පැය 12 බැගින් සමාන වේ", "පෘථිවිය මත දිවා හා රාත්‍රී කාලය සම්පූර්ණයෙන් නැති වී යයි", "සියලුම මහාද්වීප හා සාගර මත ගුරුත්වාකර්ෂණය නැති වී යයි", "පෘථිවියේ සියලුම සාගර ජලය වාෂ්ප වී කාන්තාර බවට පත් වේ",
        "අක්ෂයේ 23.5° ආනතිය සෘතු වෙනසට හා දිවා-රාත්‍රී දිග වෙනසට මූලික හේතුවයි."),
      q(t, "රාත්‍රී අහසේ දිශාව හඳුනා ගැනීමට උතුරු අර්ධගෝලයේ නාවිකයන්ට සැමවිටම සත්‍ය උතුර පෙන්වන තාරකාව කුමක්ද?",
        "උත්තර ධ්‍රැවයට ඉහළින් පිහිටි ධ්‍රැව තාරකාව (Polaris)", "රාත්‍රී අහසේ දීප්තිමත්ම තරුව වන සිරියස් තාරකාව", "දකුණු අර්ධගෝලයේ දිස්වන දක්ෂිණ කුරුස තාරකා රාශිය", "හිරු බැස යාමෙන් පසු පෙනෙන සිකුරු ග්‍රහලෝකය",
        "පෘථිවි උත්තර ධ්‍රැව අක්ෂයට කෙළින්ම ඉහළින් පිහිටි බැවින් Polaris සැමවිටම උතුර දක්වයි."),
      q(t, "චන්ද්‍රයාගේ හා සූර්යයාගේ ගුරුත්වාකර්ෂණ බලය හේතුවෙන් මුහුදු ජල මට්ටමේ දෛනික ඉහළ-පහළ යාම හඳුන්වන්නේ කුමන නමින්ද?",
        "ගුරුත්ව බලයෙන් ඇතිවන වඩදිය සහ බාදිය (Tides)", "සාගර පතුලේ භූමිකම්පා නිසා හටගන්නා සුනාමි රළ", "සුළං මඟින් සමකයේ සිට ගලන සාගර උණුසුම් දියවැල්", "ධ්‍රැවීය ග්ලැසියර දියවීමෙන් සිදුවන මුහුදු මට්ටම ඉහළ යාම",
        "චන්ද්‍රයා, සූර්යයා සහ පෘථිවිය එකම රේඛාවේ පිහිටන පුර පසළොස්වක හා අමාවක දිනවල Spring Tides ඇතිවේ."),
      q(t, "පුර පසළොස්වක සහ අමාවක දිනවලදී ඇතිවන උපරිම වඩදිය (Spring Tides) තත්ත්වයට මූලික හේතුව කුමක්ද?",
        "සූර්යයා, චන්ද්‍රයා සහ පෘථිවිය එක පෙළට පිහිටා ගුරුත්ව බල එකතු වීම", "සාගර පතුලේ නිරන්තර ගිනිකඳු පිපිරීම් හා භූමිකම්පා ඇතිවීම", "සාගර මතුපිට හමන වෙළඳ සුළංවල වේගය අඩුවී නිශ්චල වීම", "ධ්‍රැව ප්‍රදේශවල සාගර ජලය අධික ලෙස කැටි ගැසී ගන වීම",
        "මීට ප්‍රතිවිරුද්ධව අටවක දිනවල 90° කෝණයකින් පිහිටි විට අඩු වඩදිය (Neap Tides) ඇතිවේ."),
      q(t, "කාලගුණ විද්‍යා සිතියමක සමපීඩන රේඛා (Isobars) ඉතා සමීපව පිහිටා ඇති ප්‍රදේශයක අපේක්ෂා කළ හැකි කාලගුණික තත්ත්වය කුමක්ද?",
        "ඉහළ පීඩන අනුක්‍රමණයක් නිසා හටගන්නා ඉතා තද ප්‍රචණ්ඩ සුළං", "සුළඟක් නොමැති සම්පූර්ණයෙන්ම නිශ්චල හා පැහැදිලි වායුගෝලයක්", "මාස ගණනාවක් පුරා පවතින දැඩි වියළි නියඟ කාලගුණ තත්ත්වයක්", "වර්ෂාවක් නොමැතිව සිදුවන අධික හිම මිදීමේ තත්ත්වයක් පමණි",
        "පීඩන අනුක්‍රමණය (Pressure Gradient) වැඩි වන තරමට සුළඟේ වේගය අධික වේ."),
      q(t, "සමාන වලාකුළු ආවරණයක් ඇති ස්ථාන යා කර කාලගුණ සිතියමක අඳින රේඛා මොනවාද?",
        "සමාන වලාකුළු ප්‍රමාණය දක්වන සමමේඝ රේඛා (Isonephs)", "සමාන වායු පීඩනය දක්වන සමපීඩන රේඛා (Isobars)", "සමාන ලවණතාව දක්වන සමලවණ රේඛා (Isohalines)", "සමාන උෂ්ණත්වය දක්වන සමෝෂ්ණ රේඛා (Isotherms)",
        "වලාකුළු ප්‍රමාණය අටෙන් කොටස් (Oktas) ලෙස මැන Isonephs මඟින් සිතියම්ගත කෙරේ."),
      q(t, "සාගර ජලයේ සමාන ලවණතාවක් (Salinity) පවතින ස්ථාන යා කරමින් අඳින ලද සමරේඛා හඳුන්වන්නේ කුමන නමින්ද?",
        "සමාන ලවණතා මට්ටම් යා කරන සමලවණ රේඛා (Isohalines)", "සමාන වර්ෂාපතන අගයන් යා කරන සමවර්ෂා රේඛා (Isohyets)", "සමාන උන්නතාංශ අගයන් යා කරන සමෝච්ච රේඛා (Contours)", "සමාන සූර්යාලෝක පැය ගණන යා කරන සමසූර්ය රේඛා (Isohels)",
        "උපනිවර්තන සාගරවල වාෂ්පීභවනය අධික බැවින් ලවණතාව ඉහළ අගයක් ගනී."),
      q(t, "යම් කිසි නගරයක ස්වභාවික දේශීය හිරු වේලාව (Local Solar Time) මධ්‍යහ්න 12.00 වන්නේ කුමන අවස්ථාවේදීද?",
        "එම නගරයේ දේශාංශයට සෘජුවම ඉහළින් සූර්යයා මුදුන් වන මොහොතේ", "පුර පසළොස්වක දිනයේදී නැගෙනහිර ක්ෂිතිජයෙන් සඳු උදාවන මොහොතේ", "සූර්යයා බටහිර ක්ෂිතිජයෙන් සම්පූර්ණයෙන්ම බැස යන සවස 6.00 මොහොතේ", "මධ්‍යම රාත්‍රියෙන් පසුව එළඹෙන අලුයම 3.00 මොහොතේදී",
        "සෑම දේශාංශයකටම එයට අනන්‍ය ස්වභාවික හිරු වේලාවක් පැවතියද රටවල් පහසුව සඳහා සම්මත වේලාව භාවිත කරයි."),
      q(t, "ශ්‍රී ලංකාවේ (UTC +5:30) සහ තායිලන්තයේ බැංකොක් නුවර (UTC +7:00) අතර පවතින නිල වේලා වෙනස කීයද?",
        "බැංකොක් නුවර ශ්‍රී ලංකාවට වඩා පැය 1 විනාඩි 30 ක් ඉදිරියෙනි", "බැංකොක් නුවර ශ්‍රී ලංකාවට වඩා පැය 3 විනාඩි 00 ක් පසුපසිනි", "රටවල් දෙකෙහිම ක්‍රියාත්මක වන්නේ එකම සම්මත වේලාවකි", "බැංකොක් නුවර ශ්‍රී ලංකාවට වඩා පැය 5 විනාඩි 00 ක් ඉදිරියෙනි",
        "UTC +7:00 සහ UTC +5:30 අතර වෙනස පැය 1 විනාඩි 30 කි."),
      q(t, "සූර්යග්‍රහණයක් (Solar Eclipse) ඇතිවීමේදී අභ්‍යවකාශයේ සූර්යයා, චන්ද්‍රයා සහ පෘථිවිය පිහිටන අනුපිළිවෙළ කුමක්ද?",
        "සූර්යයා — චන්ද්‍රයා — පෘථිවිය (චන්ද්‍රයා මැද පිහිටයි)", "සූර්යයා — පෘථිවිය — චන්ද්‍රයා (පෘථිවිය මැද පිහිටයි)", "චන්ද්‍රයා — සූර්යයා — පෘථිවිය (සූර්යයා මැද පිහිටයි)", "පෘථිවිය — සිකුරු — සූර්යයා (සිකුරු මැද පිහිටයි)",
        "අමාවක දිනයකදී චන්ද්‍රයා සූර්යයා හා පෘථිවිය අතරට පැමිණ සූර්යාලෝකය අවහිර කරන විට සූර්යග්‍රහණය සිදුවේ."),
      q(t, "චන්ද්‍රග්‍රහණයක් (Lunar Eclipse) සිදුවන්නේ කුමන චන්ද්‍ර කලාවේදී සහ කුමන පිහිටීම නිසාද?",
        "පුර පසළොස්වක දිනකදී පෘථිවිය හිරු හා සඳු අතරට පැමිණීමෙන්", "අමාවක දිනකදී චන්ද්‍රයා හිරු හා පෘථිවිය අතරට පැමිණීමෙන්", "අටවක දිනකදී චන්ද්‍රයා හා සූර්යයා සෘජුකෝණීව පිහිටීමෙන්", "චන්ද්‍රයා පෘථිවිය වටා කක්ෂයේ උපරිම දුරට ගමන් කිරීමෙන්",
        "පෘථිවියේ සෙවණැල්ල චන්ද්‍රයා මතට වැටීමෙන් චන්ද්‍රග්‍රහණය සිදුවේ."),
      q(t, "දකුණු අර්ධගෝලයේ පිහිටි ඕස්ට්‍රේලියාවේ දෙසැම්බර් 25 වන දින උදාවන්නේ කුමන සෘතුව තුළද?",
        "උණුසුම් කාලගුණයක් ඇති ගිම්හාන සෘතුව තුළ", "අධික හිම පතනය සහිත ශීත සෘතුව තුළ", "මල් පිපෙන මෘදු වසන්ත සෘතුව තුළ", "ගස්වල පත්‍ර හැලෙන සරත් සෘතුව තුළ",
        "දෙසැම්බරයේ සූර්යයා මකර නිවර්තනය මත බබළන බැවින් දකුණු අර්ධගෝලයේ එය උණුසුම් ගිම්හාන සමයයි."),
      q(t, "ශ්‍රී ලංකාවට සූර්යයා සෘජුවම මුදුන් වීම (Zenith Sun) වසරක් තුළදී කී වරක් සිදුවේද?",
        "අප්‍රේල් සහ අගෝස්තු-සැප්තැම්බර් ලෙස වසරකට දෙවරක්", "ජූනි මාසයේදී පමණක් වසරකට එක් වරක් පමණි", "සෘතු හතර අනුව වසරකට සතර වරක් පමණි", "නිවර්තන සීමාවෙන් පිටත නිසා කිසිදා සිදු නොවේ",
        "සූර්යයා සමකයේ සිට කර්කටක නිවර්තනයට යන විට අප්‍රේල් මසද, ආපසු එන විට අගෝස්තු-සැප්තැම්බර් මසද ලංකාවට මුදුන් වේ."),
      q(t, "පෘථිවි භ්‍රමණයේ රේඛීය වේගය උපරිම වන්නේත් ධ්‍රැව දෙසට අඩු වන්නේත් කුමන ආකාරයකටද?",
        "සමකය මත උපරිම වී ධ්‍රැව දෙසට යත්ම අඩු වේ", "ධ්‍රැව දෙක මත උපරිම වී සමකය දෙසට අඩු වේ", "සමකයේ සිට ධ්‍රැව දක්වාම එකම වේගයකින් පවතී", "කර්කටක හා මකර නිවර්තන රේඛා මත ශුන්‍ය වේ",
        "සමකයේ පරිධිය විශාලම නිසා පැය 24 දී වැඩිම දුරක් (ආසන්නව 1,670 km/h) ගමන් කරයි."),
      q(t, "ටෝකියෝ (UTC +9) සහ ඉන්දියාවේ නවදිල්ලිය (UTC +5:30) අතර පවතින නිල වේලා වෙනස කීයද?",
        "ටෝකියෝව නවදිල්ලියට වඩා පැය 3 විනාඩි 30 ක් ඉදිරියෙනි", "ටෝකියෝව නවදිල්ලියට වඩා පැය 2 විනාඩි 00 ක් පසුපසිනි", "ටෝකියෝව නවදිල්ලියට වඩා පැය 5 විනාඩි 00 ක් ඉදිරියෙනි", "නගර දෙකෙහිම කාල කලාප අගයන් සමාන වේ",
        "UTC +9:00 සහ UTC +5:30 අතර වෙනස පැය 3 විනාඩි 30 කි."),
      q(t, "ශ්‍රී ලංකාවේ බටහිර වෙරළේ පුත්තලම (80° E) හා නැගෙනහිර වෙරළේ මඩකලපුව (81.7° E) අතර සූර්යෝදයේ වෙනස කුමක්ද?",
        "මඩකලපුවට හිරු පුත්තලමට වඩා මිනිත්තු 7 ක් කලින් උදාවේ", "පුත්තලමට හිරු මඩකලපුවට වඩා පැය 1 ක් කලින් උදාවේ", "දිවයින කුඩා නිසා නගර දෙකටම එකම තත්පරයේ හිරු උදාවේ", "මඩකලපුවට හිරු පුත්තලමට වඩා පැය 2 ක් පසුව උදාවේ",
        "පෘථිවිය බටහිර සිට නැගෙනහිරට භ්‍රමණය වන නිසා නැගෙනහිරට හිරු කලින් උදාවේ (1.7° × 4 min ≈ 7 min)."),
      q(t, "ග්‍රිනිච් වේලාවට (0°) වඩා පැය 4 ක් ඉදිරියෙන් පවතින ස්ථානයක් පිහිටා ඇති දේශාංශය කුමක්ද?",
        "නැගෙනහිර දේශාංශ අංශක 60° (60° E)", "බටහිර දේශාංශ අංශක 60° (60° W)", "නැගෙනහිර දේශාංශ අංශක 45° (45° E)", "නැගෙනහිර දේශාංශ අංශක 120° (120° E)",
        "පැය 1 = 15° බැවින් පැය 4 = 4 × 15° = 60°; ඉදිරියෙන් නිසා නැගෙනහිර (E) වේ."),
      q(t, "ලන්ඩන් නුවර (0°) මධ්‍යහ්න 12.00 වන විට පෙ.ව. 9.00 පෙන්වන නගරයක් පිහිටා ඇති දේශාංශය කුමක්ද?",
        "බටහිර දේශාංශ අංශක 45° (45° W)", "නැගෙනහිර දේශාංශ අංශක 45° (45° E)", "බටහිර දේශාංශ අංශක 90° (90° W)", "බටහිර දේශාංශ අංශක 30° (30° W)",
        "පැය 3 ක් පසුපසින් (12 - 9 = 3) පවතින බැවින් 3 × 15° = 45° W වේ."),
      q(t, "සමකාසන්න සිංගප්පූරුව (1° N) සහ ජපානය (36° N) අතර දෙසැම්බර් මාසයේ දිවා කාලයේ දිග සැසඳූ විට නිවැරදි කුමක්ද?",
        "සිංගප්පූරුවේ පැය 12 ක් පමණ වුවද ජපානයේ දිවා කාලය කෙටිය", "ජපානයේ දිවා කාලය පැය 20 ක් පමණ වන විට සිංගප්පූරුව කෙටිය", "දෙසැම්බර් මාසයේදී රටවල් දෙකෙහිම දිවා කාලයේ දිග සමාන වේ", "සිංගප්පූරුවේ හිම වැටී ජපානයේ උණුසුම් ගිම්හාන කාලගුණයක් පවතී",
        "දෙසැම්බර් උතුරු අර්ධගෝලයේ ශීත සෘතුව බැවින් සමකයෙන් උතුරට යත්ම දිවා කාලය කෙටි වේ."),
      q(t, "උතුරු අර්ධගෝලයේ නැවක් කෙටිම මාර්ගය ඔස්සේ යුරෝපයේ සිට උතුරු ඇමරිකාවට යාමට භාවිත කරන ජ්‍යාමිතික රේඛාව කුමක්ද?",
        "ගෝලයේ කෙටිම දුර දක්වන මහා වෘත්ත මාර්ගය", "පෘථිවි මධ්‍යයේ පිහිටි 0° සමක අක්ෂාංශ රේඛාව", "දකුණු අර්ධගෝලයේ 23.5° S මකර නිවර්තන රේඛාව", "උතුරු සෞම්‍ය කලාපයේ 45° N අක්ෂාංශ සමාන්තර රේඛාව",
        "ගෝලයක් මත ලක්ෂ්‍ය දෙකක් අතර කෙටිම දුර Great Circle චාපයක් ඔස්සේ ගමන් කරයි."),
      q(t, "පෘථිවියේ චුම්භක ක්ෂේත්‍රය (Magnetic Field) මිනිසාට හා ජීවීන්ට ලබා දෙන වැදගත්ම ස්වාභාවික ආරක්ෂාව කුමක්ද?",
        "හානිකර සූර්ය සුළං හා විකිරණවලින් වායුගෝලය ආරක්ෂා කිරීම", "පෘථිවිය මත අධික ගංවතුර ඇති කරන මෝසම් වර්ෂාව නතර කිරීම", "භූ තැටි ගැටීමෙන් ඇතිවන කඳු වැටි හා ගිනිකඳු නිර්මාණය කිරීම", "මුහුදු ජලයේ අඩංගු ඛනිජ ලවණ ප්‍රමාණය ඉහළ නැංවීම",
        "චුම්බක ගෝලය (Magnetosphere) සූර්යයාගෙන් එන ආරෝපිත අංශු හරවා යවයි."),
      q(t, "උතුරු අර්ධගෝලයේ ජූනි 21 දින මධ්‍යම රාත්‍රී සූර්යයා නැරඹිය හැකි ප්‍රසිද්ධ නෝර්වීජියානු නගරය කුමක්ද?",
        "ආක්ටික් වෘත්තයට උතුරින් පිහිටි නෝර්වේහි ට්‍රොම්සෝ නගරය", "සමකයට ආසන්න ඉන්දියානු සාගරයේ කොළඹ නගරය", "මලක්කා සමුද්‍ර සන්ධියේ පිහිටි සිංගප්පූරු නගරය", "නැගෙනහිර අප්‍රිකාවේ කෙන්යාවේ පිහිටි නයිරෝබි නගරය",
        "ආක්ටික් වෘත්තයට උතුරින් පිහිටි නෝර්වේ, ෆින්ලන්ත හා අයිස්ලන්ත ප්‍රදේශවල Midnight Sun දැකිය හැකිය."),
      q(t, "අන්තර්ජාතික ගුවන් හා කාලගුණ වාර්තාවලදී ලොව පුරා පොදු සම්මත කාලය ලෙස භාවිත කරන 'UTC' යන්නෙහි අර්ථය කුමක්ද?",
        "සම්බන්ධීකරණ විශ්ව කාලය (Coordinated Universal Time)", "එක්සත් කලාපීය ජාතික වේලාව (United Time Zone)", "මධ්‍යම යුරෝපීය දේශීය වේලාව (Central European Time)", "සූර්ය අභ්‍යන්තර මධ්‍ය කාලය (Solar Internal Time)",
        "UTC යනු පරමාණුක ඔරලෝසු මත පදනම් වූ නූතන ගෝලීය සම්මත වේලාවයි (GMT හා සමීපව ගැළපේ)."),
      q(t, "සෞම්‍ය කලාපීය රටවල ගිම්හාන කාලයේදී දිවා ආලෝකයෙන් උපරිම ප්‍රයෝජන ගැනීමට ඔරලෝසු පැයක් ඉදිරියට ගැනීමේ ක්‍රමය කුමක්ද?",
        "දිවා ආලෝක ඉතිරි කිරීමේ වේලාව (Daylight Saving Time)", "අධික වර්ෂාපතන කාලීන වේලාව (Monsoon Time)", "චන්ද්‍ර මාස පාදක කාල ක්‍රමය (Lunar Time)", "දිවා රාත්‍රී සමාන විෂුව වේලාව (Equinox Time)",
        "යුරෝපය හා උතුරු ඇමරිකාව වැනි සෞම්‍ය රටවල් ගිම්හානයේදී විදුලිය ඉතිරි කිරීමට DST භාවිත කරයි."),
      q(t, "සමකාසන්න රටක් වන ශ්‍රී ලංකාවට 'Daylight Saving Time' (DST) අවශ්‍ය නොවීමට භූගෝලීය හේතුව කුමක්ද?",
        "වසර පුරාම දිවා කාලයේ දිගෙහි සැලකිය යුතු වෙනසක් නොමැති වීම", "ශ්‍රී ලංකාව උත්තර ධ්‍රැවයට ඉතා ආසන්නව පිහිටා තිබීම", "දිවයින තුළ වසරේ මාස කිහිපයකදී රාත්‍රී කාලය නොමැති වීම", "රට තුළ දෛනික කටයුතු සඳහා විදුලි බලය අවශ්‍ය නොවීම",
        "සමකය අසල දිවා කාලය වසර පුරා පැය 11.5 - 12.5 අතර ස්ථාවරව පවතී."),
      q(t, "ග්‍රිනිච් මධ්‍ය රේඛාව (0°) හා කොළඹ (80° E) අතර භූගෝලීය දේශීය සූර්ය වේලා වෙනස ගණනය කළහොත් කොපමණද?",
        "පැය 5 විනාඩි 20 ක් ඉදිරියෙනි", "පැය 6 විනාඩි 20 ක් ඉදිරියෙනි", "පැය 4 විනාඩි 20 ක් ඉදිරියෙනි", "පැය 2 විනාඩි 20 ක් ඉදිරියෙනි",
        "80° × 4 min = 320 min = පැය 5 විනාඩි 20 කි. එහෙත් සම්මත වේලාව 82.5°E මත පැය 5 විනාඩි 30 ලෙස ගනී."),
      q(t, "පෘථිවිය සිය අක්ෂය වටා කැරකෙන දිශාව හේතුවෙන් සූර්යයා උදාවන බව පෙනෙන්නේ කුමන දිශාවෙන්ද?",
        "බටහිර සිට නැගෙනහිරට භ්‍රමණය නිසා නැගෙනහිර දිශාවෙන්", "නැගෙනහිර සිට බටහිරට භ්‍රමණය නිසා බටහිර දිශාවෙන්", "උතුරේ සිට දකුණට භ්‍රමණය නිසා දකුණු දිශාවෙන්", "දකුණේ සිට උතුරට භ්‍රමණය නිසා උතුරු දිශාවෙන්",
        "පෘථිවිය බටහිර සිට නැගෙනහිරට කැරකීම නිසා සූර්යයා නැගෙනහිරින් පායා බටහිරින් බැස යන සේ දිස්වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'උතුරු හා දකුණු' අන්ත දෙක වන පේදුරු තුඩුව සහ දෙවුන්දර තුඩුව අතර අක්ෂාංශ අන්තරය ආසන්නව අංශක කීයද?",
        "උතුරු අක්ෂාංශ අංශක 4 ක් පමණි", "උතුරු අක්ෂාංශ අංශක 20 ක් පමණි", "උතුරු අක්ෂාංශ අංශක 10 ක් පමණි", "උතුරු අක්ෂාංශ අංශක 45 ක් පමණි",
        "අක්ෂාංශ 1° ≈ 111 km බැවින් අංශක ~3.9 × 111 ≈ 432 km දිගක් උතුරේ සිට දකුණට පවතී."),
      q(t, "පෘථිවිය ධ්‍රැව දෙකේදී තරමක් පැතලි වී සමකයේදී නෙරා තිබීමෙන් සෑදෙන ජ්‍යාමිතික හැඩය කුමක්ද?",
        "ධ්‍රැව දෙක පැතලි වූ ධ්‍රැවාභ ගෝලාභය (Oblate Spheroid)", "සෑම දිශාවකින්ම සමාන පැති ඇති සම්පූර්ණ ඝනකය", "වෘත්තාකාර පාදම් දෙකක් සහිත සෘජු සිලින්ඩරය", "උල් වූ මුදුනක් සහිත පැතලි පාදම් කේතුව",
        "පෘථිවි භ්‍රමණයේ කේන්ද්‍රාපසාරී බලය නිසා සමක විෂ්කම්භය (12,756 km) ධ්‍රැව විෂ්කම්භයට (12,714 km) වඩා වැඩිය."),
      q(t, "පෘථිවියේ සමක පරිධිය (Equatorial Circumference) ආසන්න වශයෙන් කිලෝමීටර් කීයක් වේද?",
        "ආසන්න වශයෙන් කිලෝමීටර් 40,075 කි", "ආසන්න වශයෙන් කිලෝමීටර් 12,756 කි", "ආසන්න වශයෙන් කිලෝමීටර් 6,371 කි", "ආසන්න වශයෙන් කිලෝමීටර් 100,000 කි",
        "සමක පරිධිය ~40,075 km වන අතර ධ්‍රැවීය පරිධිය ~40,008 km කි."),
      q(t, "සමකයේ සිට උතුරට හෝ දකුණට යන විට අක්ෂාංශ වෘත්තවල (Parallels) විෂ්කම්භය කෙසේ වෙනස් වේද?",
        "සමකයේදී විශාලම වී ධ්‍රැව දෙසට යත්ම ක්‍රමයෙන් කුඩා වේ", "සමකයේදී කුඩාම වී ධ්‍රැව දෙසට යත්ම ක්‍රමයෙන් විශාල වේ", "සමකයේ සිට ධ්‍රැව දක්වාම සමාන විෂ්කම්භයකින් යුක්ත වේ", "අංශක 60° අක්ෂාංශයේදී සමකයටත් වඩා විශාලම අගය ගනී",
        "අක්ෂාංශ සමාන්තර වුවද ඒවායේ වෘත්ත පරිධිය ධ්‍රැව දෙසට අඩු වේ."),
      q(t, "ඕනෑම දේශාංශ රේඛාවක් (Meridian) සහ එහි ප්‍රතිවිරුද්ධ දේශාංශ රේඛාව එක්වී නිර්මාණය වන්නේ කුමක්ද?",
        "පෘථිවිය සමව බෙදන සම්පූර්ණ මහා වෘත්තයකි", "ධ්‍රැව ආසන්නයේ පිහිටන කුඩා අක්ෂාංශ වෘත්තයකි", "සමකයට සමාන්තරව දිවෙන සමාන්තර රේඛාවකි", "නිවර්තන දෙක අතර පිහිටි තාප කලාපයකි",
